INSERT INTO fut_sbc_log VALUES(13,1,'FC27',10,27,'2026-09-26','GK Lola Gallardo(82) · RCB Nordi Mukiele(81) · CB Andrea Medina(82) · LCB Hailie Mace(81) · CDM Ryan Christie(78) · RM Miguel Rodríguez(72) · RCM 바리오스(83) · LCM Alex Scott(81) · LM Keane Lewis-Potter(81) · RS Benjamin Šeško(82) · LS Nahikari(73)','사용자가 화면에서 완료 처리(2026-09-26) — EA·fut.gg가 주지 않는 축이라 사람이 적는다','MEASURED(사용자 행위). ⚠️ 제출 카드는 **우리가 제안한 11장**으로 적었다 — 다른 조합으로 내셨다면 사실과 다르다(되돌리려면 완료 취소).','5 Leagues & 6 Nations');
INSERT INTO fut_sbc_log VALUES(14,1,'FC27',10,26,'2026-09-26',NULL,'사용자가 화면에서 완료 처리(2026-09-26) — 우리 제안과 **다른 조합**으로 제출','MEASURED(사용자 행위). ⚠️ 제출 카드는 **모른다** — 우리 해법과 다른 조합이라 squad_note를 비운다. 소모된 카드는 다음 클럽 싱크가 잡는다.','4 Leagues & 5 Nations');
